61	/**
62	 * AIDispatcher - Autonomous capability selection and execution.
63	 * Refactored to use unified ModelClient substrate.
64	 */
65	export class AIDispatcher {
66	    private readonly serviceStates: Map<AIServiceType, ServiceState> = new Map();
67	
68	    constructor(
69	        private readonly client: ModelClient,
70	        private readonly workforce: WorkforceManifest
71	    ) {
72	        // Initialize service states
73	        const types: AIServiceType[] = ['GEMINI', 'CLOUDFLARE', 'OLLAMA', 'HUGGINGFACE'];
74	        types.forEach(t => this.serviceStates.set(t, 'IDLE'));
75	    }
76	
77	    async dispatch(request: { capabilityId: string; payload: string; context?: any; snapshot?: RoutingSnapshot; modelOverride?: string }): Promise<Result<any>> {
78	        const capability = CapabilityRegistry[request.capabilityId];
79	        if (!capability) {
80	            return { ok: false, error: new Error(`Capability ${request.capabilityId} not registered.`) };
81	        }
82	
83	        const taskClass = capability.taskClass || this.classifyTask(request.capabilityId, request.payload);
84	        const policy = MODEL_POLICY[taskClass] || MODEL_POLICY.AGENTIC_REASONING;
85	        
86	        // Use provided snapshot or get current from CNS
87	        const snapshot = request.snapshot || CNSGodheadPulseVolley.getInstance()?.getRoutingSnapshot();
88	
89	        const modelId = request.modelOverride || this.resolveModelFromPolicy(policy, capability, snapshot);
90	        
91	        const start = Date.now();
92	        try {
93	            this.serviceStates.set(capability.serviceType, 'READY');
94	            const result = await this.client.execute({
95	                model: modelId,
96	                prompt: request.payload,
97	                systemPrompt: `Capability: ${capability.name}\nTask: ${taskClass}\nDomain: ${capability.domain || 'GENERAL'}`
98	            });
99	
100	            const latency = Date.now() - start;
101	            
102	            // Causal Routing Audit
103	            this.auditDecision({
104	                tick: snapshot?.tick || -1,
105	                taskClass,
106	                policy,
107	                snapshotHash: snapshot ? this.hashSnapshot(snapshot) : 'LIVE',
108	                selectedModel: modelId,
109	                selectedTier: this.getTierFromModel(modelId, capability),
110	                latencyMs: latency,
111	                success: result.ok
112	            });
113	
114	            return result;
115	        } catch (error) {
116	            this.serviceStates.set(capability.serviceType, 'ERROR');
117	            const errorMessage = error instanceof Error ? error.message : String(error);
118	
119	            if (capability.fallback) {
120	                logger.warn({ capabilityId: request.capabilityId, fallback: capability.fallback, error: errorMessage }, 'Dispatch exception, attempting fallback');
121	                return this.dispatch({ ...request, capabilityId: capability.fallback });
122	            }
123	
124	            return {
125	                ok: false,
126	                error: new Error(errorMessage)
127	            };
128	        }
129	    }
130	
131	    private classifyTask(id: string, payload: string): TaskClass {
132	        if (id.includes('vision') || id.includes('eye') || payload.includes('.png')) return "VISION";
133	        if (id.includes('search') || id.includes('retrieve') || id.includes('atlas')) return "RETRIEVAL";
134	        if (id.includes('completion') || id.includes('scaffold')) return "COMPLETION";
135	        if (id.includes('generate') || id.includes('creative')) return "CREATIVE_EXPANSION";
136	        return "AGENTIC_REASONING";
137	    }
138	
139	    private resolveModelFromPolicy(policy: RoutingPolicy, capability: AICapability, snapshot?: RoutingSnapshot): string {
140	        const rolodex = this.client.getRolodex();
141	        
142	        // 0. Policy-Driven Cloud Gate
143	        let cloudStatus = 'ONLINE';
144	        let cloudEffect = 'NONE';
145	
146	        if (snapshot) {
147	            cloudStatus = snapshot.cloudHealth.status;
148	            cloudEffect = snapshot.cloudHealth.effect;
149	        } else {
150	            const signal = SubstrateResolver.getCloudSignal();
151	            cloudStatus = signal.status;
152	            cloudEffect = signal.effect;
153	        }
154	
155	        const forceLocal = !policy.allowCloud || cloudEffect === 'BLOCK_CLOUD_TASKS';
156	
157	        // 1. Try Primary Tier (if not forced local or primary is already local)
158	        if (!forceLocal || policy.primary !== 'CLOUD') {
159	            const primaryModel = this.getModelForTier(policy.primary, capability);
160	            const isHealthy = snapshot ? snapshot.modelHealthMap[primaryModel] : rolodex?.isModelHealthy(primaryModel);
161	            if (isHealthy) return primaryModel;
162	        }
163	
164	        // 2. Try Fallback Tiers in order
165	        for (const tier of policy.fallback) {
166	            if (forceLocal && tier === 'CLOUD') continue;
167	            const fallbackModel = this.getModelForTier(tier, capability);
168	            const isHealthy = snapshot ? snapshot.modelHealthMap[fallbackModel] : rolodex?.isModelHealthy(fallbackModel);
169	            if (isHealthy) return fallbackModel;
170	        }
171	
172	        // 3. Absolute Floor: Sovereign Local
173	        return this.getModelForTier("SOVEREIGN_LOCAL", capability);
174	    }
175	
176	    private getModelForTier(tier: ModelTier, capability: AICapability): string {
177	        switch (tier) {
178	            case "SOVEREIGN_LOCAL": 
179	                return this.client.config.masterLocalModel || 'deepseek-r1:8b';
180	            case "ENRICHED_LOCAL": 
181	                return this.client.config.localFallbackModel || 'deepseek-r1:8b';
182	            case "CLOUD": 
183	                return capability.modelId || this.client.config.orchestratorModel;
184	        }
185	    }
186	
187	    private getTierFromModel(modelId: string, capability: AICapability): ModelTier {
188	        if (modelId === (this.client.config.masterLocalModel || 'deepseek-r1:8b')) return "SOVEREIGN_LOCAL";
189	        if (modelId === capability.modelId) return "CLOUD";
190	        return "ENRICHED_LOCAL";
191	    }
192	
193	    private hashSnapshot(snapshot: RoutingSnapshot): string {
194	        // Simple hash of the snapshot state
195	        const data = `${snapshot.tick}-${snapshot.cloudHealth.status}-${snapshot.substrateHealth}`;
196	        return `snap:${snapshot.tick}`;
197	    }
198	
199	    private auditDecision(audit: RoutingDecisionAudit): void {
200	        logger.info({
201	            tick: audit.tick,
202	            task: audit.taskClass,
203	            model: audit.selectedModel,
204	            snap: audit.snapshotHash,
205	            tier: audit.selectedTier
206	        }, '🧬 Cognitive Routing Audit');
207	
208	        EventBus.getInstance().publish({
209	            type: 'decision.routing',
210	            source: 'AIDispatcher',
211	            payload: {
212	                ...audit,
213	                timestamp: new Date().toISOString(),
214	                sessionId: (globalThis as any).pog2_sessionId || 'unknown'
215	            }
216	        });
217	    }
218	
219	    public getServiceState(type: AIServiceType): ServiceState {
220	        return this.serviceStates.get(type) || 'IDLE';
221	    }
222	
223	    public healthCheck(): { online: boolean; details: string } {
224	        const statuses = Array.from(this.serviceStates.entries())
225	            .map(([type, state]) => `${type}: ${state}`)
226	            .join(', ');
227	        return {
228	            online: true,
229	            details: `AI Dispatcher ready. Service States: ${statuses}`
230	        };
231	    }
232	}
