61	/**
62	 * ModelRolodex â€” The Sovereign's Living Model Catalog.
63	 *
64	 * Dynamically discovers available models from each provider via API/shell calls.
65	 * Tracks per-model health (success/failure/latency/tokens).
66	 * Persists state to D:\sovereign
67	olodex.json for cross-session memory.
68	 * Ollama models are always the sovereign final fallback.
69	 */
70	export class ModelRolodex {
71	    private static instance?: ModelRolodex;
72	
73	    public static getInstance(): ModelRolodex | undefined {
74	        return ModelRolodex.instance;
75	    }
76	
77	    public state: RolodexState;
78	    private readonly persistPath: string;
79	    private refreshInProgress = false;
80	
81	    constructor(private readonly config: SovereignConfig) {
82	        ModelRolodex.instance = this;
83	        this.persistPath = join(config.pog2Dir || process.cwd(), 'rolodex.json');
84	
85	        // Attempt to load persisted state
86	        if (existsSync(this.persistPath)) {
87	            try {
88	                this.state = JSON.parse(readFileSync(this.persistPath, 'utf8'));
89	                logger.info({ models: Object.keys(this.state.models).length }, 'ðŸ—‚ï¸ Rolodex loaded from disk.');
90	
91	                // Phase 21: Reputation Healing - Restore baseline for unused/corrupted states
92	                for (const key in this.state.models) {
93	                    const m = this.state.models[key];
94	                    if (m.successCount === 0 && m.failureCount === 0 && m.reputation < 1.0) {
95	                        m.reputation = 1.0;
96	                    }
97	                    if (m.reputation < 0.2) {
98	                        m.reputation = 0.2; // Enforce absolute physiological floor
99	                    }
100	                }
101	            } catch {
102	                this.state = this.createEmptyState();
103	            }
104	        } else {
105	            this.state = this.createEmptyState();
106	        }
107	
108	        // Phase 9: Start Reputation Decay Interval
109	        const decayRate = config.reputationDecayRate || 0.05;
110	        // Interval: 1 hour in production, 1 minute in development/test
111	        const intervalMs = process.env.NODE_ENV === 'test' ? 60000 : 3600000;
112	        (setInterval(() => this.applyReputationDecay(decayRate), intervalMs) as any).unref();
113	    }
114	
115	    private createEmptyState(): RolodexState {
116	        const providers: Record<RolodexProvider, ProviderIdentity> = {
117	            ollama: { provider: 'ollama', authenticated: false, models: [], latencyMs: 0, lastChecked: 0 },
118	            cloudflare: { provider: 'cloudflare', authenticated: false, models: [], latencyMs: 0, lastChecked: 0 },
119	            gemini: { provider: 'gemini', authenticated: false, models: [], latencyMs: 0, lastChecked: 0 },
120	            huggingface: { provider: 'huggingface', authenticated: false, models: [], latencyMs: 0, lastChecked: 0 },
121	            fireworks: { provider: 'fireworks', authenticated: false, models: [], latencyMs: 0, lastChecked: 0 },
122	            openrouter: { provider: 'openrouter', authenticated: false, models: [], latencyMs: 0, lastChecked: 0 },
123	            rsmv: { provider: 'rsmv', authenticated: true, models: ['rsmv-substrate'], latencyMs: 0, lastChecked: Date.now() }
124	        };
125	        return { models: {}, providers, lastRefresh: 0, version: '1.0.0' };
