210	    /** Get provider identity & status */
211	
212	    // Add inside ModelRolodex class:
213	
214	    /**
215	     * Resolve capability tier to best healthy local model.
216	     * Checks health, reputation, walks fallback chain.
217	     */
218	    public resolveCapability(tier: string): { model: string; ctx: number; reputation: number } | null {
219	        const cap = getCapability(tier);
220	        if (!cap) return null;
221	
222	        // Preferred
223	        if (this.isModelHealthy(cap.preferredModel)) {
224	            const key = `ollama:${cap.preferredModel}`;
225	            const rep = this.state.models[key]?.reputation ?? 1.0;
226	            if (rep > 0.3) return { model: cap.preferredModel, ctx: cap.minCtx, reputation: rep };
227	        }
228	
229	        // Fallback chain
230	        for (const fb of cap.fallbackModels) {
231	            if (fb === cap.preferredModel) continue;
232	            if (this.isModelHealthy(fb)) {
233	                const key = `ollama:${fb}`;
234	                const rep = this.state.models[key]?.reputation ?? 0.5;
235	                if (rep > 0.2) {
236	                    logger.info({ tier, fallback: fb }, 'Capability fallback');
237	                    return { model: fb, ctx: cap.minCtx, reputation: rep };
238	                }
239	            }
240	        }
241	
242	        // Emergency: any healthy text model
243	        const emergency = this.getAllModels()
244	            .filter(m => m.provider === 'ollama' && m.taskType === 'text' && m.reputation > 0.2)
245	            .sort((a, b) => b.reputation - a.reputation)[0];
246	
247	        if (emergency) {
248	            logger.warn({ tier, emergency: emergency.id }, 'Emergency fallback');
249	            return { model: emergency.id, ctx: 4096, reputation: emergency.reputation };
250	        }
251	
252	        return null;
253	    }
254	
255	    /**
256	     * If modelOrTier is a capability name, resolve it. Otherwise pass through.
257	     */
258	    public resolveModelOrCapability(modelOrTier: string): { model: string; ctx: number; isCapability: boolean; reputation: number } {
259	        if (isCapabilityTier(modelOrTier)) {
260	            const resolved = this.resolveCapability(modelOrTier);
261	            if (resolved) return { ...resolved, isCapability: true };
262	        }
263	        return {
264	            model: modelOrTier,
265	            ctx: 4096,
266	            isCapability: false,
267	            reputation: this.state.models[`ollama:${modelOrTier}`]?.reputation ?? 1.0
268	        };
269	    }
270	
271	    /** Check if ALL cloud providers are down (triggers sovereign Ollama override) */
272	    isAllCloudDown(): boolean {
273	        const cloudProviders: RolodexProvider[] = ['cloudflare', 'gemini', 'huggingface', 'fireworks', 'openrouter'];
274	        return cloudProviders.every(p => {
