392	    /** ðŸ§¬ Reputation Scoring Algorithm - Research Grade */
393	    private computeReputation(m: RolodexModel): number {
394	        const totalCalls = m.successCount + m.failureCount;
395	        if (totalCalls === 0) return 1.0;
396	
397	        // 1. Success Rate Component (60%)
398	        const successRate = m.successCount / totalCalls;
399	
400	        // 2. Latency Component (30%) - Normalized (0.1 effectively infinite, 1.0 instant)
401	        // Assume 50ms is "instant" and 5000ms is "stalled"
402	        const latencyFactor = Math.max(0, 1 - (m.avgLatencyMs / 5000));
403	
404	        // 3. Cost/Token Penalty (10%) - Discourage massive token burns without success
405	        const tokenPenalty = Math.min(0.1, (m.totalTokensUsed / 1_000_000) * 0.1);
406	
407	        const score = (successRate * 0.6) + (latencyFactor * 0.3) + 0.1 - tokenPenalty;
408	        // ðŸ§¬ Phase 108: Clamping to physiological bounds (0.2 to 2.0)
409	        return Math.max(0.2, Math.min(2.0, score));
410	    }
