969	            model.reputation = model.reputation + (1.0 - model.reputation) * decayRate;
970	        }
971	
972	        logger.debug({ decayRate, count }, 'ðŸ§¬ Reputation decay applied: All models drifted toward baseline.');
973	        this.persist();
974	    }
